import heapq

def match(orders):
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    book = {}       # id -> dict(side, price, qty, seq)
    seq_counter = 0
    trades = []

    def clean_heap(heap):
        while heap:
            item = heap[0]
            oid = item[2]
            if oid not in book or book[oid]['qty'] <= 0:
                heapq.heappop(heap)
            else:
                break

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                del book[oid]
            continue

        oid = order[1]
        side = order[2]
        if typ == 'market':
            qty = order[3]
            price = None
        else:
            price = order[3]
            qty = order[4]

        remaining = qty
        seq_counter += 1
        my_seq = seq_counter

        if side == 'buy':
            opp_heap = sell_heap
            while remaining > 0:
                clean_heap(opp_heap)
                if not opp_heap:
                    break
                top_price, opp_seq, opp_id = opp_heap[0]
                opp_price = top_price  # sell heap stores price directly
                if typ != 'market' and opp_price > price:
                    break
                trade_qty = min(remaining, book[opp_id]['qty'])
                trades.append([oid, opp_id, opp_price, trade_qty])
                remaining -= trade_qty
                book[opp_id]['qty'] -= trade_qty
                if book[opp_id]['qty'] == 0:
                    del book[opp_id]
                    heapq.heappop(opp_heap)

            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'seq': my_seq}
                heapq.heappush(buy_heap, (-price, my_seq, oid))

        else:  # sell
            opp_heap = buy_heap
            while remaining > 0:
                clean_heap(opp_heap)
                if not opp_heap:
                    break
                neg_price, opp_seq, opp_id = opp_heap[0]
                opp_price = -neg_price
                if typ != 'market' and opp_price < price:
                    break
                trade_qty = min(remaining, book[opp_id]['qty'])
                trades.append([opp_id, oid, opp_price, trade_qty])
                remaining -= trade_qty
                book[opp_id]['qty'] -= trade_qty
                if book[opp_id]['qty'] == 0:
                    del book[opp_id]
                    heapq.heappop(opp_heap)

            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'seq': my_seq}
                heapq.heappush(sell_heap, (price, my_seq, oid))

    return trades

